<?php
session_start();if(!isset($_SESSION['userName'])||$_SESSION['userName']!=='admin'){header('Location: alogin.php');exit;}require_once 'dbconfig.php';$statusFilter=trim($_GET['status']??'');$allowed=['Bekliyor','Onaylandı','Tamamlandı','İptal Edildi'];if(!in_array($statusFilter,$allowed,true))$statusFilter='';$sql="SELECT b.appointment_id,b.Fname,b.Username,b.DOV,b.appointment_time,b.Status,b.Timestamp,d.Name AS doctor_name,c.Name AS clinic_name,c.Town FROM book b LEFT JOIN doctor d ON d.DID=b.DID LEFT JOIN clinic c ON c.CID=b.CID";if($statusFilter!=='')$sql.=" WHERE (CASE WHEN b.Status='Booked' OR TRIM(b.Status)='' THEN 'Bekliyor' ELSE b.Status END)=?";$sql.=" ORDER BY b.DOV DESC,b.appointment_time DESC";$stmt=$conn->prepare($sql);if($statusFilter!=='')$stmt->bind_param('s',$statusFilter);$stmt->execute();$result=$stmt->get_result();$count=$result->num_rows;function statusText($s){return $s==='Booked'||trim((string)$s)===''?'Bekliyor':$s;}function statusClass($s){switch(statusText($s)){case'Onaylandı':return'approved';case'Tamamlandı':return'completed';case'İptal Edildi':return'cancelled';default:return'pending';}}?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Randevular | Appointment</title><link rel="stylesheet" href="adminmain.css"><style>.admin-wrap{width:min(1250px,calc(100% - 32px));margin:30px auto 60px}.page-head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:20px}.page-head h1{margin:5px 0 7px;font-size:32px}.page-head p{margin:0;color:var(--admin-muted)}.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:15px}.filter{padding:9px 13px;border:1px solid var(--admin-border);border-radius:9px;background:#fff;text-decoration:none;color:var(--admin-text);font-size:12px;font-weight:800}.filter.active{background:var(--admin-primary);color:#fff;border-color:var(--admin-primary)}.table-card{padding:0;overflow:hidden}.table-top{display:flex;justify-content:space-between;align-items:center;padding:18px 20px;border-bottom:1px solid var(--admin-border)}.table-top h2{margin:0;font-size:17px}.count{padding:6px 10px;border-radius:999px;background:#eaf2ff;color:var(--admin-primary);font-size:12px;font-weight:800}.table-wrap{overflow:auto}.data-table{width:100%;border-collapse:collapse;min-width:1050px}.data-table th,.data-table td{padding:13px 15px;border-bottom:1px solid var(--admin-border);text-align:left;font-size:13px}.data-table th{background:#f8fafc;color:#647084;font-size:10px;text-transform:uppercase;letter-spacing:.05em}.data-table tr:hover{background:#fbfdff}.id,.time{font-variant-numeric:tabular-nums;font-weight:800;white-space:nowrap}.person,.doctor,.clinic{font-weight:800}.sub{display:block;color:var(--admin-muted);font-size:11px;margin-top:2px}.status{display:inline-flex;padding:6px 9px;border-radius:999px;font-size:11px;font-weight:800;white-space:nowrap}.pending{background:#fff3cd;color:#856404}.approved{background:#e7f6ec;color:#16713a}.completed{background:#e7f0ff;color:#2457a6}.cancelled{background:#fde8e8;color:#a32929}.actions{white-space:nowrap}.action-btn{border:0;border-radius:7px;padding:7px 9px;margin:2px;font-size:11px;font-weight:800;cursor:pointer}.approve{background:#e7f6ec;color:#16713a}.complete{background:#e7f0ff;color:#2457a6}.cancel{background:#fde8e8;color:#a32929}.action-btn:disabled{opacity:.45;cursor:not-allowed}.empty{padding:35px;text-align:center;color:var(--admin-muted)}@media(max-width:600px){.admin-wrap{width:calc(100% - 20px);margin-top:18px}.page-head{align-items:flex-start;flex-direction:column}.page-head .admin-button{width:100%}.filters{overflow:auto;flex-wrap:nowrap;padding-bottom:3px}.filter{white-space:nowrap}}</style></head><body><header class="admin-topbar"><a class="admin-brand" href="mainpage.php"><img src="cal.png" alt="Appointment"><span>Appointment</span></a><nav class="admin-nav"><a class="active" href="showappointments.php">Randevular</a><a href="mainpage.php">Panel</a><a href="showdoctor.php">Doktorlar</a><a href="showclinic.php">Klinikler</a><a href="showmanager.php">Managerlar</a></nav></header><main class="admin-wrap"><div class="page-head"><div><span class="admin-eyebrow">RANDEVU YÖNETİMİ</span><h1>Randevular</h1><p>Randevuları filtreleyin ve durumlarını tek ekrandan yönetin.</p></div><a class="admin-button secondary" href="mainpage.php">Panele Dön</a></div><div class="filters"><a class="filter <?php echo $statusFilter===''?'active':'';?>" href="showappointments.php">Tümü</a><?php foreach($allowed as $s):?><a class="filter <?php echo $statusFilter===$s?'active':'';?>" href="showappointments.php?status=<?php echo urlencode($s);?>"><?php echo htmlspecialchars($s);?></a><?php endforeach;?></div><section class="admin-card table-card"><div class="table-top"><h2>Randevu listesi</h2><span class="count"><?php echo $count;?> kayıt</span></div><?php if(!$count):?><div class="empty">Bu filtreye uygun randevu bulunamadı.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Tarih</th><th>Saat</th><th>Hasta</th><th>Doktor</th><th>Klinik</th><th>Durum</th><th>İşlem</th><th>Oluşturulma</th></tr></thead><tbody><?php while($r=$result->fetch_assoc()):$st=statusText($r['Status']);?><tr><td class="id">#<?php echo (int)$r['appointment_id'];?></td><td><?php echo $r['DOV']?htmlspecialchars(date('d.m.Y',strtotime($r['DOV']))):'-';?></td><td class="time"><?php echo $r['appointment_time']?htmlspecialchars(substr($r['appointment_time'],0,5)):'-';?></td><td><span class="person"><?php echo htmlspecialchars($r['Fname']);?></span><span class="sub"><?php echo htmlspecialchars($r['Username']);?></span></td><td class="doctor"><?php echo htmlspecialchars($r['doctor_name']??'Doktor');?></td><td><span class="clinic"><?php echo htmlspecialchars($r['clinic_name']??'Klinik');?></span><span class="sub"><?php echo htmlspecialchars($r['Town']??'');?></span></td><td><span class="status <?php echo statusClass($r['Status']);?>"><?php echo htmlspecialchars($st);?></span></td><td class="actions"><?php if($st==='Bekliyor'):?><button class="action-btn approve" data-id="<?php echo (int)$r['appointment_id'];?>" data-status="Onaylandı">Onayla</button><?php endif;?><?php if($st==='Onaylandı'):?><button class="action-btn complete" data-id="<?php echo (int)$r['appointment_id'];?>" data-status="Tamamlandı">Tamamlandı</button><?php endif;?><?php if($st!=='Tamamlandı'&&$st!=='İptal Edildi'):?><button class="action-btn cancel" data-id="<?php echo (int)$r['appointment_id'];?>" data-status="İptal Edildi">İptal Et</button><?php endif;?></td><td class="sub"><?php echo htmlspecialchars($r['Timestamp']);?></td></tr><?php endwhile;?></tbody></table></div><?php endif;?></section></main><script>document.querySelectorAll('.action-btn').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.id,status=b.dataset.status;if(!confirm(status==='İptal Edildi'?'Bu randevu iptal edilsin mi?':'Randevu "'+status+'" durumuna geçirilsin mi?'))return;b.disabled=true;const f=new FormData();f.append('appointment_id',id);f.append('status',status);try{const r=await fetch('admin_update_appointment.php',{method:'POST',body:f});const d=await r.json();if(!d.success)throw new Error(d.message||'İşlem başarısız.');location.reload()}catch(e){alert(e.message);b.disabled=false}}));</script></body></html><?php $stmt->close();$conn->close();?>